// Step 7: assert answer.json against all four source datasets. Exit 1 on any mismatch.
const fs = require('fs');
const path = require('path');

const REGIONS = ['north', 'south', 'east', 'west'];
const dir = __dirname;
let failures = 0;

function ok(msg) { console.log('ok    ' + msg); }
function fail(msg) { failures++; console.log('FAIL  ' + msg); }
function eq(label, actual, expected) {
  if (Object.is(actual, expected)) ok(label + ' = ' + expected);
  else fail(label + ': got ' + actual + ', expected ' + expected);
}
function eqJSON(label, actual, expected) {
  const a = JSON.stringify(actual), e = JSON.stringify(expected);
  if (a === e) ok(label + ' = ' + e);
  else fail(label + ': got ' + a + ', expected ' + e);
}
function isInt(label, v) {
  if (Number.isInteger(v)) ok(label + ' is an integer (' + v + ')');
  else fail(label + ' is not an integer: ' + v);
}

// ---- load answer.json ----
let ans;
try {
  ans = JSON.parse(fs.readFileSync(path.join(dir, 'answer.json'), 'utf8'));
} catch (e) {
  console.log('FAIL  answer.json is not valid JSON: ' + e.message);
  process.exit(1);
}
if (!ans || typeof ans !== 'object' || Array.isArray(ans)) {
  console.log('FAIL  answer.json top level is not an object');
  process.exit(1);
}

// ---- schema ----
eqJSON('answer.json top-level keys', Object.keys(ans).sort(), ['grand_units', 'grand_weighted', 'regions']);
if (!ans.regions || typeof ans.regions !== 'object' || Array.isArray(ans.regions)) {
  fail('regions is not an object');
  process.exit(failures ? 1 : 0);
}
eqJSON('regions keys (exact)', Object.keys(ans.regions).sort(), REGIONS.slice().sort());

// ---- per-region values recomputed from the sources ----
const totals = { count: 0, units: 0, weighted: 0 };
const answerSum = { units: 0, weighted: 0 };

for (const region of REGIONS) {
  const file = path.join(dir, region + '.json');
  let src;
  try {
    src = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (e) {
    fail(region + '.json could not be read/parsed: ' + e.message);
    continue;
  }
  if (!Array.isArray(src)) { fail(region + '.json top level is not an array'); continue; }

  // source-record completeness: every record well formed, ids present/unique/contiguous, no gaps
  const ids = new Set();
  let recordsOk = true;
  src.forEach((rec, i) => {
    if (!rec || typeof rec !== 'object' || Array.isArray(rec)) { fail(region + ' record ' + i + ' is not an object'); recordsOk = false; return; }
    for (const f of ['id', 'units', 'weight']) {
      if (!Number.isInteger(rec[f])) { fail(region + ' record ' + i + ' field ' + f + ' is not an integer: ' + rec[f]); recordsOk = false; }
    }
    if (Number.isInteger(rec.units) && rec.units < 0) { fail(region + ' record ' + i + ' has negative units'); recordsOk = false; }
    if (Number.isInteger(rec.weight) && rec.weight < 0) { fail(region + ' record ' + i + ' has negative weight'); recordsOk = false; }
    if (ids.has(rec.id)) { fail(region + ' duplicate id ' + rec.id); recordsOk = false; }
    ids.add(rec.id);
    const product = rec.units * rec.weight;
    if (!Number.isInteger(product)) { fail(region + ' record ' + i + ' product is not an integer: ' + product); recordsOk = false; }
  });
  if (recordsOk) ok(region + ' all ' + src.length + ' records well formed, ids unique (' + ids.size + ' distinct)');

  const count = src.length;
  const units = src.reduce((a, r) => a + r.units, 0);
  const weighted = src.reduce((a, r) => a + r.units * r.weight, 0);
  console.log('      ' + region + ': records=' + count + ' units=' + units + ' weighted=' + weighted);

  const entry = ans.regions[region];
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) { fail('ans.regions.' + region + ' is missing or not an object'); continue; }
  eqJSON(region + ' entry keys (exact)', Object.keys(entry).sort(), ['count', 'units', 'weighted']);
  isInt(region + '.count', entry.count);
  isInt(region + '.units', entry.units);
  isInt(region + '.weighted', entry.weighted);
  eq(region + '.count', entry.count, count);
  eq(region + '.units', entry.units, units);
  eq(region + '.weighted', entry.weighted, weighted);

  totals.count += count;
  totals.units += units;
  totals.weighted += weighted;
  answerSum.units += Number(entry.units);
  answerSum.weighted += Number(entry.weighted);
}

// ---- grand totals ----
isInt('grand_units', ans.grand_units);
isInt('grand_weighted', ans.grand_weighted);
eq('grand_units', ans.grand_units, totals.units);
eq('grand_weighted', ans.grand_weighted, totals.weighted);
eq('grand_units vs sum of answer regions', answerSum.units, totals.units);
eq('grand_weighted vs sum of answer regions', answerSum.weighted, totals.weighted);
console.log('      source records: ' + totals.count + ', units: ' + totals.units + ', weighted: ' + totals.weighted);

// ---- verdict ----
if (failures > 0) {
  console.log('RESULT: FAILED - ' + failures + ' assertion(s) did not hold');
  process.exit(1);
}
console.log('RESULT: PASSED - answer.json matches all four sources and is complete');
process.exit(0);
